CREATE TABLE public.fishing_spot_species (
    fishing_spot_id integer NOT NULL,
    species_id uuid NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE ONLY public.fishing_spot_species ADD CONSTRAINT fishing_spot_species_pkey PRIMARY KEY (fishing_spot_id, species_id);

ALTER TABLE ONLY public.fishing_spot_species ADD CONSTRAINT fishing_spot_species_species_id_fkey FOREIGN KEY (species_id) REFERENCES public.fishing_species(id) ON DELETE CASCADE;

CREATE INDEX fishing_spot_species_species_idx ON public.fishing_spot_species USING btree (species_id);